const { spawn } = require("node:child_process");
const args = ["-y","@topline-build/harness-mcp@0.9.2"];
const env = { ...process.env, TOPLINE_WORKSPACE_ROOT: process.env.TOPLINE_WORKSPACE_ROOT || process.env.CLAUDE_PROJECT_DIR || process.cwd() };
if (!env.TOPLINE_API_URL || env.TOPLINE_API_URL.includes("${")) {
  delete env.TOPLINE_API_URL;
  try {
    const fs = require("node:fs"), path = require("node:path"), os = require("node:os");
    const dir = path.join(os.homedir(), ".topline", "build-mcp");
    const signedIn = fs.readdirSync(dir).filter(name => name.endsWith(".json")).map(name => {
      try { const file = path.join(dir, name), saved = JSON.parse(fs.readFileSync(file, "utf8"));
        return typeof saved.issuer === "string" && /^https:\/\/[^/]+$/.test(saved.issuer) && saved.resource === `${saved.issuer}/mcp/topline`
          ? { issuer: saved.issuer, at: fs.statSync(file).mtimeMs } : null; } catch { return null; }
    }).filter(Boolean).sort((a, b) => b.at - a.at);
    if (signedIn[0]) env.TOPLINE_API_URL = signedIn[0].issuer;
  } catch {}
  if (!env.TOPLINE_API_URL) { process.stderr.write("Topline needs your Topline address. Sign in once, then start a new chat: npx -y @topline-build/harness-mcp@0.9.2 login --url https://<your-account>.topline.build\n"); process.exit(1); }
}
const child = process.platform === "win32"
  ? spawn("cmd.exe", ["/d", "/s", "/c", "npx", ...args], { stdio: "inherit", windowsHide: true, env })
  : spawn("npx", args, { stdio: "inherit", env });
child.on("error", () => { process.stderr.write("Could not start Topline. Install Node.js and npm.\n"); process.exit(1); });
child.on("exit", code => process.exit(code ?? 1));
for (const signal of ["SIGINT", "SIGTERM"]) process.on(signal, () => child.kill(signal));
